CREATE TABLE Libros(
	IdLibro BIGINT NOT NULL PRIMARY KEY IDENTITY(1,1),
	IdEstado INT NOT NULL FOREIGN KEY REFERENCES [Estados](IdEstado),
	IdEditorial BIGINT NOT NULL FOREIGN KEY REFERENCES Editoriales(IdEditorial),
	FotoLibro NVARCHAR(MAX) NOT NULL,
	Libro VARCHAR(MAX) NOT NULL,
	[Version] VARCHAR(MAX) NULL,
	ISBN VARCHAR(MAX) NOT NULL,
	AnioPublicacion INT NOT NULL,
	Descripcion VARCHAR(MAX) NOT NULL,
	Cantidad INT NOT NULL,

	UsuarioCreacion VARCHAR(MAX) NOT NULL,
	FechaCreacion DATETIME NOT NULL,
	UsuarioModificacion VARCHAR(MAX) NULL,
	FechaModificacion DATETIME NULL
)

SET IDENTITY_INSERT [Libros] ON
INSERT INTO [Libros](IdLibro, IdEstado, IdEditorial, FotoLibro, Libro, [Version], ISBN, AnioPublicacion, Descripcion, Cantidad, UsuarioCreacion, FechaCreacion)
VALUES	(1, 1, 1, 'data:image/jpeg;base64,', 'Origen', 'N/A', '9788408177081', 2017, 'España es el escenario donde se sitúa la nueva novela de Dan Brown, Origen. Barcelona, Bilbao, Madrid y Sevilla son las ciudades principales en las que transcurre la nueva aventura de Robert Langdon. Robert Langdon, profesor de simbología e iconografía religiosa de la universidad de Harvard, acude al Museo Guggenheim Bilbao para asistir a un trascendental anuncio que «cambiará la faz de la ciencia para siempre». El anfitrión de la velada es Edmond Kirsch, un joven multimillonario cuyos visionarios inventos tecnológicos y audaces predicciones lo han convertido en una figura de renombre mundial. Kirsch, uno de los alumnos más brillantes de Langdon años atrás, se dispone a revelar un extraordinario descubrimiento que dará respuesta a las dos preguntas que han obsesionado a la humanidad desde el principio de los tiempos.', 10, 'SysAdmin', GETDATE()),
		(2, 1, 2, 'data:image/webp;base64,', 'Assassins Creed - Renaissance', 'N/A', '9788497341431', 2010, '"Buscaré la venganza contra aquellos que traicionaron a mi familia. Soy Ezio Auditore di Firenze. Soy un assassin…". Traicionado por las familias que gobiernan Florencia, Venecia y Roma en la Italia del Renacimiento, el joven Ezio Auditore se embarca en una épica lucha por erradicar la corrupción y restaurar el honor de su familia. Para ello deberá aprender el arte de la muerte. En su camino de venganza y lucha se encontrará con las grandiosas mentes de Leonardo da Vinci y Maquiavelo; deberá decidir entre el amor y su destino y descubrirá que este último es mucho más complejo y elevado de lo que nunca imaginó. Para sus aliados, Ezio se convertirá en la fuerza que les guiará en pos de la libertad y la justicia. Para sus enemigos, en una amenaza consagrada a la destrucción de los tiranos que abusan del pueblo italiano. Una historia épica de poder y venganza en la que la verdad se escribirá con sangre.', 10, 'SysAdmin', GETDATE());
